import ChoreoModeler from 'chor-js/lib/Modeler';
import PropertiesPanelModule from 'bpmn-js-properties-panel';

import Reporter from './lib/validator/Validator.js';
import PropertiesProviderModule from './lib/properties-provider';

import xml from './diagrams/pizzaDelivery.bpmn';
import blankXml from './diagrams/newDiagram.bpmn';

let lastFile;
let isValidating = false;
let isDirty = false;

let currChoreography = {}

const choreographyApiURL = "http://localhost:8000/api/choreographies/"

// create and configure a chor-js instance
const modeler = new ChoreoModeler({
  container: '#canvas',
  propertiesPanel: {
    parent: '#properties-panel'
  },
  // remove the properties' panel if you use the Viewer
  // or NavigatedViewer modules of chor-js
  additionalModules: [
    PropertiesPanelModule,
    PropertiesProviderModule
  ],
  keyboard: {
    bindTo: document
  }
});

// display the given model (XML representation)
async function renderModel(newXml) {
  await modeler.importXML(newXml);
  isDirty = false;
}

function page_load() {
    console.log("Handle page load ...")
}

function enterBusyState(icon=null) {
    if (icon) {
        let element = document.getElementById(icon)

        if (element) {
            element.classList.add("fa-blink")
        }
    }
}

function exitBusyState(icon=null) {
    if (icon) {
        let element = document.getElementById(icon)

        if (element) {
            element.classList.remove("fa-blink")
        }
    }
}


// returns the file name of the diagram currently being displayed
function diagramName() {
  if (lastFile) {
    return lastFile.name;
  }
  return 'diagram.bpmn';
}

function loadChoreographyFromURL(url) { 
    return fetch(url)
        .then((response) => {
            if (! response.ok) {
                window.alert("Error downloading resource")
                return
            } 
            return response.text()
        })
        .then((content) => {
            renderModel(content);
        })
        .catch((err) => {
            window.alert(`Error loading resource: ${err}`)
        })
}

function loadPopupREI() {
    let rei = currChoreography["rei"]

    if (rei) {
        let popupContentEl = document.getElementById("reiPopupContent")
        //popupContentEl.innerHTML = rei
        popupContentEl.value = rei

    } 
}

document.addEventListener('DOMContentLoaded', () => {
  // download diagram as XML
  const downloadLink = document.getElementById('js-download-diagram');
  downloadLink.addEventListener('click', async e => {
    const result = await modeler.saveXML({ format: true });
    downloadLink['href'] = 'data:application/bpmn20-xml;charset=UTF-8,' + encodeURIComponent(result.xml);
    downloadLink['download'] = diagramName();
    isDirty = false;
  });

  // download diagram as SVG
  const downloadSvgLink = document.getElementById('js-download-svg');
  downloadSvgLink.addEventListener('click', async e => {
    const result = await modeler.saveSVG();
    downloadSvgLink['href'] = 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(result.svg);
    downloadSvgLink['download'] = diagramName() + '.svg';
  });

  // open file url
  document.getElementById('js-open-url').addEventListener('click', e => {

    let url = window.prompt("Provide the URL of the diagram you want to load:") //document.getElementById('diagram-url').value
    if (! url) {
        return
    }
    loadChoreographyFromURL(url)
        .then(() => {
            currChoreography = { "resource": url }
        })
  });

  // open popup with REI
  
  document.getElementById('js-display-rei').addEventListener('click', e => {
    let rei = currChoreography["rei"]

    if (! rei) {
        window.alert(`No REI to display for current choreography`)
        return
    }

    loadPopupREI()

    let popupEl = document.getElementById("reiPopup")
    popupEl.classList.toggle("show")

  });


  document.getElementById('js-rei-hide').addEventListener('click', e => {
        let popupEl = document.getElementById("reiPopup")
        popupEl.classList.remove("show")
  })

  document.getElementById('js-rei-copy').addEventListener('click', e => {
        let popupContentInput = document.getElementById("reiPopupContent")

        popupContentInput.select()
        popupContentInput.setSelectionRange(0,100000)
        navigator.clipboard.writeText(popupContentInput.value)
        window.alert("REI copied to clipboard!")
  })



  // open file dialog
  document.getElementById('js-open-file').addEventListener('click', e => {
    document.getElementById('file-input').click();
  });

  // save file dialog
  document.getElementById('js-save-diagram').addEventListener('click', async e => {

    const saveData = new FormData()
    const result = await modeler.saveXML({ format: true });
    let blob = new Blob([result.xml], {type:"application/xml"}) 
    let bpmnFile = new File([blob], currChoreography["name"] + ".bpmn")

    saveData.append("resource", bpmnFile)
    saveData.append("name", currChoreography["name"])

    let choreographyURL = currChoreography["url"]

    enterBusyState("js-save-diagram")
    fetch(choreographyURL, { "method": "PUT", "body": saveData })
        .then((resp) => {
            updateChoreographyList(currChoreography["name"])
            exitBusyState("js-save-diagram")
            window.alert(`Choreography updated succesfully!`)
        })
        .catch((err) => {
            exitBusyState("js-save-diagram")
            window.alert(`Error updating choreography: ${err}`)
        })
  });



  // toggle side panels
  const panels = Array.prototype.slice.call(
    document.getElementById('panel-toggle').children
  );
  panels.forEach(panel => {
    panel.addEventListener('click', () => {
      panels.forEach(otherPanel => {
        if (panel === otherPanel && !panel.classList.contains('active')) {
          // show clicked panel if it is not already active, otherwise hide it as well
          panel.classList.add('active');
          document.getElementById(panel.dataset.togglePanel).classList.remove('hidden');
        } else {
          // hide all other panels
          otherPanel.classList.remove('active');
          document.getElementById(otherPanel.dataset.togglePanel).classList.add('hidden');
        }
      });
    });
  });

  // create new diagram
  const newDiagram = document.getElementById('js-new-diagram');
  newDiagram.addEventListener('click', async e => {
    await renderModel(blankXml);
    lastFile = false;
  });

  // load diagram from disk
  const loadDiagram = document.getElementById('file-input');
  loadDiagram.addEventListener('change', e => {
    const file = loadDiagram.files[0];
    if (file) {
      const reader = new FileReader();
      lastFile = file;
      reader.addEventListener('load', async () => {
        await renderModel(reader.result);
        loadDiagram.value = null; // allows reloading the same file
      }, false);
      reader.readAsText(file);
    }
  });

  // drag & drop file
  const dropZone = document.body;
  dropZone.addEventListener('dragover', e => {
    e.preventDefault();
    dropZone.classList.add('is-dragover');
  });
  dropZone.addEventListener('dragleave', e => {
    e.preventDefault();
    dropZone.classList.remove('is-dragover');
  });
  dropZone.addEventListener('drop', e => {
    e.preventDefault();
    dropZone.classList.remove('is-dragover');
    const file = e.dataTransfer.files[0];
    if (file) {
      const reader = new FileReader();
      lastFile = file;
      reader.addEventListener('load', () => {
        renderModel(reader.result);
      }, false);
      reader.readAsText(file);
    }
  });

  // validation logic and toggle
  const reporter = new Reporter(modeler);
  const validateButton = document.getElementById('js-validate');
  validateButton.addEventListener('click', e => {
    isValidating = !isValidating;
    if (isValidating) {
      reporter.validateDiagram();
      validateButton.classList.add('selected');
      validateButton['title'] = 'Disable checking';
    } else {
      reporter.clearAll();
      validateButton.classList.remove('selected');
      validateButton['title'] = 'Check diagram for problems';
    }
  });
  modeler.on('commandStack.changed', () => {
    if (isValidating) {
      reporter.validateDiagram();
    }
    isDirty = true;
  });
  modeler.on('import.render.complete', () => {
    if (isValidating) {
      reporter.validateDiagram();
    }
  });
});

// expose bpmnjs to window for debugging purposes
window.bpmnjs = modeler;

window.addEventListener('beforeunload', function(e) {
  if (isDirty) {
    // see https://developer.mozilla.org/en-US/docs/Web/API/WindowEventHandlers/onbeforeunload
    e.preventDefault();
    e.returnValue = '';
  }
});

renderModel(xml);

const choreographySelect = document.getElementById("js-select-choreography")
choreographySelect.addEventListener('change', e => {
    if (e.target.value) {
        let currOption = e.target.selectedOptions[0]

        if (currOption) {
            window.location.hash = "#" + currOption.text
        } else if (! currOption) {
            window.location.hash = ""
        }
        loadChoreographyFromURL(currOption.dataset.resource)
            .then(() => {
                currChoreography = { "resource": currOption.dataset.resource, "id": currOption.dataset.id, "name": currOption.dataset.name, "url": currOption.dataset.url, "rei": currOption.dataset.rei }
                loadPopupREI()
            })
    } else {
        renderModel(blankXml);
    }
})

function updateChoreographyList(name=null) {

    choreographySelect.innerHTML = "<option value=''>---</option>"
    fetch(choreographyApiURL)
        .then((response) => {
            return response.json()
        })
        .then((data) => {
            let found = false
            let oldSelected = choreographySelect.selectedOptions ? choreographySelect.selectedOptions[0].value : ""
            for (let curr of data) {
                let selected = (name && name == curr['name']) ? "selected" : ""
                found = found || (selected != "")
                choreographySelect.innerHTML += `<option ${selected} value="${curr['id']}" data-name="${curr['name']}" data-id="${curr['id']}" data-resource="${curr['resource']}" data-url="${choreographyApiURL + curr['id'] + '/'}" data-rei="${curr['rei']}">${curr['name']}</option>`
            }

            if (! found) {
                console.warn(`Current choreography value not found (${name})...`)
            } else {
                if (choreographySelect.selectedOptions[0].value != oldSelected) {
                    choreographySelect.dispatchEvent(new Event('change')); // trigger change event
                }

            }
        })
        .catch((err) => {
            console.error(`Cannot load choreographies: ${err}`)
        })
}

window.addEventListener("load", function () {
    console.log("Handle page load ...")
    let anchor = window.location.hash ? window.location.hash.substring(1) : ""
    updateChoreographyList(anchor)
});

